/** Game sound effects, respecting the player's setting. Failures (no audio device, web autoplay rules) are ignored. */
import { createAudioPlayer, type AudioPlayer } from 'expo-audio';

import { ensureAudioMode } from './audioMode';

export type SoundKind = 'select' | 'found' | 'warning' | 'hint' | 'complete';

// Generated by `npm run audio` (scripts/generateAudio.ts).
const SOURCES: Record<SoundKind, number> = {
  select: require('../../../assets/audio/select.wav'),
  found: require('../../../assets/audio/found.wav'),
  warning: require('../../../assets/audio/warning.wav'),
  hint: require('../../../assets/audio/hint.wav'),
  complete: require('../../../assets/audio/complete.wav'),
};

/** Mix levels: the frequent tap sound sits well under the rewarding ones. */
const VOLUME: Record<SoundKind, number> = { select: 0.35, found: 0.75, warning: 0.55, hint: 0.6, complete: 0.85 };

let enabled = true;
const players = new Map<SoundKind, AudioPlayer>();

export function setSoundEnabled(value: boolean) {
  enabled = value;
  if (value) preloadSounds();
}

function playerFor(kind: SoundKind): AudioPlayer {
  let player = players.get(kind);
  if (!player) {
    ensureAudioMode();
    player = createAudioPlayer(SOURCES[kind]);
    player.volume = VOLUME[kind];
    players.set(kind, player);
  }
  return player;
}

/** Loads every effect up front so the first one plays without a delay. */
function preloadSounds() {
  try {
    for (const kind of Object.keys(SOURCES) as SoundKind[]) playerFor(kind);
  } catch {
    // Audio unavailable on this platform.
  }
}

export function playSound(kind: SoundKind) {
  if (!enabled) return;
  try {
    const player = playerFor(kind);
    // Restart from the top, so a quick repeat (tapping tiles) replays instead of being ignored.
    player.seekTo(0).catch(() => {});
    player.play();
  } catch {
    // Audio unavailable on this platform.
  }
}
